        __import__(m)
        print(m, 'OK')
    except Exception as e:
        print(m, 'MISSING:', type(e).__name__)
for m in ['fpdf','matplotlib','reportlab','pypdf','PyPDF2','pdfplumber','weasyprint','PIL']:
    check(m)
"

